#ifndef DRIVING_DATA_XBEDATA_H_
#define DRIVING_DATA_XBEDATA_H_

// The game's data - the initial values of its tables - is not in our source: tools/extract_driving_data.py takes it
// from the user's own Driving.xbe at build time into autogenerated_data.h/.cpp (docs/driving/standalone.md). A global
// whose initial value comes from there is defined without one, under its XBE_GLOBAL tag, and XBE_INITIAL(name) beside
// it fills it before anything runs - `uint16_t PanAzimuth[128];` then `XBE_INITIAL(PanAzimuth);`. The generator
// finds each XBE_INITIAL, takes the address and size from the tag above the definition, and writes the bytes. A pointer to a string in the XBE becomes a pointer to the same text in ours.

#include <stdint.h>
#include <type_traits>

struct XbeRelocation {
    uint32_t offset;       // where in the global
    const void *target;    // what the word there points at in our copy
};

struct XbeBlob {
    const uint32_t *words;
    uint32_t size;         // bytes
    const XbeRelocation *relocations;
    uint32_t numRelocations;
};

struct XbeInitialiser {
    XbeInitialiser(void *global, uint32_t size, const XbeBlob &blob);
};

#define XBE_INITIAL(name)                                                                              \
    static_assert(sizeof(name) == XbeDataSize_##name, #name ": its size and its XBE_GLOBAL tag's differ"); \
    static_assert(std::is_trivially_copyable_v<decltype(name)>, #name ": filled by copying");             \
    static XbeInitialiser name##_xbeInitial(&(name), sizeof(name), XbeData_##name)

#include "../autogenerated_data.h"

#endif // DRIVING_DATA_XBEDATA_H_
